import com.datastax.oss.driver.api.core.CqlSession;
import com.datastax.oss.driver.api.core.cql.SimpleStatement;
import com.datastax.oss.driver.api.core.ConsistencyLevel;

public class PacelcCassandraClient {
    public void writeWithLowLatency(CqlSession session, String userId, String payload) {
        // Demonstrates the 'L' (Latency) choice in the ELC part of PACELC.
        // We sacrifice consistency (C) by writing with LOCAL_QUORUM instead of ALL.
        SimpleStatement statement = SimpleStatement.builder(
                "INSERT INTO user_events (user_id, event_payload) VALUES (?, ?)")
                .addPositionalValues(userId, payload)
                .setConsistencyLevel(ConsistencyLevel.LOCAL_QUORUM)
                .build();

        session.execute(statement);
    }
}
